namespace ghidra.app.plugin.core.debug.service.modules;





using ghidra.app.plugin.core.debug.service.modules.DebuggerStaticMappingContext;
using ghidra.app.plugin.core.debug.utils;
using ghidra.debug.api.modules;
using ghidra.framework.model;
using ghidra.program.model.address;
using ghidra.program.model.listing;
using ghidra.trace.model;
using ghidra.util;

class InfoPerProgram : DomainObjectListener {

	static class NavMultiMap<K, V> {
		private TreeMap<K, Set<V>> map = new();

		public bool put(K k, V v) {
			return map.computeIfAbsent(k, __ => new()).add(v);
		}

		public bool remove(K k, V v) {
			Set<V> set = map.get(k);
			if (set == null) {
				return false;
			}
			if (!set.remove(v)) {
				return false;
			}
			if (set.isEmpty()) {
				map.remove(k);
			}
			return true;
		}
	}

	private DebuggerStaticMappingContext ctx;
	Program program;
	NavMultiMap<Address, MappingEntry> inboundByStaticAddress = new();

	URL url;

	InfoPerProgram(DebuggerStaticMappingContext ctx, Program program) {
		this.ctx = ctx;
		this.program = program;
		this.url = ProgramURLUtils.getUrlFromProgram(program);

		program.addListener(this);
	}

	/* @Override */
	public void domainObjectChanged(DomainObjectChangedEvent ev) {
		if (ev.contains(DomainObjectEvent.FILE_CHANGED) || ev.contains(DomainObjectEvent.RENAMED)) {
			if (!urlMatches()) {
				CompletableFuture.runAsync(() => {
					using (ChangeCollector cc = ctx.collectChanges())
{
						ctx.processRemovedProgramInfo(cc, this);
						ctx.processAddedProgram(cc, program);
					}
				}, ctx.executor);
			}
		}
	}

	bool urlMatches() {
		return Objects.equals(url, ProgramURLUtils.getUrlFromProgram(program));
	}

	void clearProgram(ChangeCollector cc, MappingEntry me) {
		System.Diagnostics.Debug.Assert(me.program == program);
		inboundByStaticAddress.remove(me.getStaticAddress(), me);
		me.clearProgram(cc, program);
	}

	void fillProgram(ChangeCollector cc, MappingEntry me) {
		System.Diagnostics.Debug.Assert(me.getStaticProgramUrl().equals(ProgramURLUtils.getUrlFromProgram(program)));
		me.fillProgram(cc, program);
		inboundByStaticAddress.put(me.getStaticAddress(), me);
	}

	void clearEntries(ChangeCollector cc) {
		if (url == null) {
			return;
		}
		foreach (InfoPerTrace info in ctx.traceInfoByTrace.values()) {
			info.clearEntriesForProgram(cc, this);
		}
	}

	void fillEntries(ChangeCollector cc) {
		if (url == null) {
			return;
		}
		foreach (InfoPerTrace info in ctx.traceInfoByTrace.values()) {
			info.fillEntriesForProgram(cc, this);
		}
	}

	Set<TraceLocation> getOpenMappedTraceLocations(Address address) {
		Set<TraceLocation> result = new();
		foreach (Set<MappingEntry> set in inboundByStaticAddress.map.headMap(address, true).values()) {
			foreach (MappingEntry me in set) {
				if (me.mapping.isDeleted()) {
					Msg.warn(this, "Encountered deleted mapping: " + me.mapping);
					continue;
				}
				if (!me.isInProgramRange(address)) {
					continue;
				}
				result.add(me.mapProgramAddressToTraceLocation(address));
			}
		}
		return result;
	}

	TraceLocation getOpenMappedTraceLocation(Trace trace, Address address, long snap) {
		// TODO: Map by trace?
		foreach (Set<MappingEntry> set in inboundByStaticAddress.map.headMap(address, true).values()) {
			foreach (MappingEntry me in set) {
				if (me.mapping.isDeleted()) {
					Msg.warn(this, "Encountered deleted mapping: " + me.mapping);
					continue;
				}
				if (me.getTrace() != trace) {
					continue;
				}
				if (!me.isInProgramRange(address)) {
					continue;
				}
				if (!me.isInTraceLifespan(snap)) {
					continue;
				}
				return me.mapProgramAddressToTraceLocation(address);
			}
		}
		return null;
	}

	private void collectOpenMappedViews(Map<TraceSpan, Collection<MappedAddressRange>> result,
			AddressRange rng) {
		foreach (Set<MappingEntry> set in inboundByStaticAddress.map.headMap(rng.getMaxAddress(), true)
				.values()) {
			foreach (MappingEntry me in set) {
				if (me.mapping.isDeleted()) {
					Msg.warn(this, "Encountered deleted mapping: " + me.mapping);
					continue;
				}
				// NB. No lifespan to consider
				if (!me.isInProgramRange(rng)) {
					continue;
				}
				AddressRange srcRange = me.getStaticRange().intersect(rng);
				AddressRange dstRange = me.mapProgramRangeToTrace(rng);
				result.computeIfAbsent(me.getTraceSpan(), p => new())
						.add(new MappedAddressRange(srcRange, dstRange));
			}
		}
	}

	Map<TraceSpan, Collection<MappedAddressRange>> getOpenMappedViews(AddressSetView set) {
		Map<TraceSpan, Collection<MappedAddressRange>> result = new();
		foreach (AddressRange rng in set) {
			collectOpenMappedViews(result, rng);
		}
		return Collections.unmodifiableMap(result);
	}
}
